 "D": "Charlie Puth Attention official video",
}
def fetch(url, out):
    subprocess.run(["curl","-s","-L","-A",UA,"-b","CONSENT=YES+cb","--compressed",url,"-o",out], check=False)
for k,q in queries.items():
    fetch("https://www.youtube.com/results?search_query="+q.replace(" ","+"), f"search_{k}.html")
    doc = open(f"search_{k}.html", encoding="utf-8", errors="ignore").read()
    ids = re.findall(r'"videoRenderer":\{"videoId":"([^"]+)".{0,4000}?"title":\{"runs":\[\{"text":"(.*?)"\}', doc)
    seen=set(); out=[]
    for vid,t in ids:
        if vid in seen: continue
        seen.add(vid); out.append((vid,t))
        if len(out)>=5: break
    print(f"== {k}: {q}")
    for vid,t in out:
        print("   ", vid, t[:70])
